export type FrameworkStyle = "bdd" | "non-bdd";
export type TestingType = "ui" | "api" | "ui-api" | "performance";
export type Language = "typescript" | "javascript" | "python" | "java" | "k6";
export type JavaTestRunner = "junit" | "testng";
export interface GeneratorOptions {
    projectName: string;
    destination: string;
    language?: Language;
    javaTestRunner?: JavaTestRunner;
    framework: FrameworkStyle;
    testingType: TestingType;
    allure: boolean;
    githubActions: boolean;
    installDependencies: boolean;
}
